import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Retro — real-corpus yield: shippable = 0 on honest modules","description":"","frontmatter":{},"headers":[],"relativePath":"graphopt/project/retros/real-corpus-yield.md","filePath":"vendored/graphopt/project/retros/real-corpus-yield.md"}`),a={name:`graphopt/project/retros/real-corpus-yield.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="retro-—-real-corpus-yield-shippable-0-on-honest-modules" tabindex="-1">Retro — real-corpus yield: <code>shippable = 0</code> on honest modules <a class="header-anchor" href="#retro-—-real-corpus-yield-shippable-0-on-honest-modules" aria-label="Permalink to “Retro — real-corpus yield: shippable = 0 on honest modules”">​</a></h1><p>Date: 2026-10-05 Context: <code>project/retros/corpus-round-4.md</code> (<code>shippable: 0 -&gt; 11</code>), <code>project/retros/shippable-audit.md</code> (&quot;demonstrated usefulness is corpus-circular&quot;), commit <code>e2a4051</code> (the <code>purpose_built</code> ledger, <code>real_workloads()</code>, the <code>--real-only</code> flag). The audit <em>argued</em> circularity from <code>fire_cases</code> provenance; this retro <em>measures</em> the counterfactual: drop the 46 purpose-built spellings and re-run the whole intake -&gt; pipeline harness on what is left.</p><p><strong>Headline: <code>shippable: 0 -&gt; 0</code>.</strong> On real modules alone — the torch-native <code>nn.*</code> workloads and the realistic compound assemblies — the pipeline ships nothing. All 11 shipped rules, and every one of the 30 newly-firing guards&#39; <em>equal</em> sites, live exclusively on purpose-built workloads.</p><h2 id="the-measurement" tabindex="-1">The measurement <a class="header-anchor" href="#the-measurement" aria-label="Permalink to “The measurement”">​</a></h2><p>Two intake runs from the committed tree, same seed (0), same vocab (<code>derived</code>), no holdout:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;">.venv/bin/python</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#005CC5;"> -m</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;"> mlopt_discovery.intake</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#005CC5;"> \\</span></span>
<span class="line"><span style="--shiki-dark:#FFFFFF;--shiki-light:#005CC5;">    --out</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;"> /tmp/full_intake_corpus.json</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#005CC5;"> \\</span></span>
<span class="line"><span style="--shiki-dark:#FFFFFF;--shiki-light:#005CC5;">    --tensors</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;"> /tmp/full_intake_tensors.pt</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#005CC5;"> \\</span></span>
<span class="line"><span style="--shiki-dark:#FFFFFF;--shiki-light:#005CC5;">    --json</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;"> /tmp/full_results.json</span></span>
<span class="line"><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;">.venv/bin/python</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#005CC5;"> -m</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;"> mlopt_discovery.intake</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#005CC5;"> --real-only</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#005CC5;"> \\</span></span>
<span class="line"><span style="--shiki-dark:#FFFFFF;--shiki-light:#005CC5;">    --out</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;"> /tmp/real_intake_corpus.json</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#005CC5;"> \\</span></span>
<span class="line"><span style="--shiki-dark:#FFFFFF;--shiki-light:#005CC5;">    --tensors</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;"> /tmp/real_intake_tensors.pt</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#005CC5;"> \\</span></span>
<span class="line"><span style="--shiki-dark:#FFFFFF;--shiki-light:#005CC5;">    --json</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;"> /tmp/real_results.json</span></span></code></pre></div><p>(<code>--out</code>/<code>--tensors</code> are redirected to <code>/tmp</code> so the gitignored <code>$XDG_CACHE_HOME/mlopt/intake_corpus.json</code> stays as last generated — see <em>Caveats</em>.) Both runs ingested, measured the census delta, and ran the full baseline-vs-enlarged pipeline delta. A second probe loaded the two side-files, re-ran <code>workload_gen._run_pipeline</code> on each enlarged corpus for per-proposal <code>fire_cases</code>, and swept each of round-4&#39;s 30 newly-firing guards — as the <em>bare</em> <code>Rewrite</code> from <code>generator_pools</code> — over every corpus case via <code>real_matches</code> + <code>evidence._guarded_evals</code> (<code>torch.manual_seed(0)</code> per case), bucketing sites by provenance (<code>bench</code> / <code>model</code> / real-intake / purpose-built).</p><p>No code changed. <code>--real-only</code> is plumbed correctly end to end: <code>main</code> filters <code>candidates()</code> through <code>real_workloads()</code> before <code>ingest</code>, and ingestion, the census delta, the status table, the side-file write and the pipeline delta all consume the filtered list. No plumbing fix was needed.</p><h2 id="full-vs-real-—-the-honest-table" tabindex="-1">Full vs real — the honest table <a class="header-anchor" href="#full-vs-real-—-the-honest-table" aria-label="Permalink to “Full vs real — the honest table”">​</a></h2><p>The registry holds <strong>256</strong> candidates (the round-4 table&#39;s &quot;254&quot; was the <em>exported</em> count; 2 torch-native modules are export-rejected in both runs). <code>--real-only</code> keeps 210 of them; <code>_PURPOSE_BUILT</code> drops 46 (9 round-3 + 37 round-4 spellings).</p><table tabindex="0"><thead><tr><th>metric</th><th>baseline (bench+models)</th><th>corpus + full intake</th><th>corpus + real-only intake</th></tr></thead><tbody><tr><td>intake candidates</td><td>—</td><td>256</td><td>210</td></tr><tr><td>exported</td><td>—</td><td>254</td><td>208</td></tr><tr><td>ingested (fp64-verified)</td><td>—</td><td>201</td><td>155</td></tr><tr><td>census-only (unbound ops)</td><td>—</td><td>53</td><td>53</td></tr><tr><td>verify-failed</td><td>—</td><td>0</td><td>0</td></tr><tr><td>rejected</td><td>—</td><td>2</td><td>2</td></tr><tr><td>probe-eligible (≤120 nodes)</td><td>—</td><td>201</td><td>155</td></tr><tr><td>corpus terms</td><td>110</td><td>364</td><td>318</td></tr><tr><td>op-tuples</td><td>211</td><td>725</td><td>702</td></tr><tr><td>new op-tuples vs baseline</td><td>—</td><td>514</td><td>491</td></tr><tr><td>new shapes</td><td>—</td><td>1112</td><td>1066</td></tr><tr><td>new ops</td><td>—</td><td>193</td><td>193</td></tr><tr><td>proposals</td><td>54</td><td>79</td><td>79</td></tr><tr><td>new proposals</td><td>—</td><td>27</td><td>25</td></tr><tr><td>proposals with <code>fires &gt; 0</code></td><td>—</td><td>69</td><td>41</td></tr><tr><td>proposals with <code>paid &gt; 0</code></td><td>—</td><td>33</td><td>9</td></tr><tr><td><strong>shippable</strong></td><td><strong>0</strong></td><td><strong>11</strong></td><td><strong>0</strong></td></tr></tbody></table><p>Three readings:</p><ol><li><p><strong>The spellings add no ops.</strong> All 193 previously-absent ops, and the entire census-only backlog, come from real modules — the purpose-built subset contributes only 23 op-tuples and 46 shapes of pure <em>re-spelling</em>. That is what it was for.</p></li><li><p><strong>The real corpus is not dead — it is just unshippable.</strong> 41 proposals still fire on the real corpus (the e-graph applies the bare pattern somewhere) and 9 still pay. Every paying proposal is refused at <code>truth</code> (conditional equality — the view oracle&#39;s &quot;no single mechanical feature separates&quot; / <code>w:v_commutes_view</code> verdicts) except <code>grammar:sub_to_add_dup</code> (<code>not new</code>) and <code>grammar:mul_distribute</code> (never lowers cost). The unguarded unconditional equalities — the class that can clear the truth gate — simply do not occur on real modules.</p></li><li><p><strong><code>shippable</code> is entirely the spellings.</strong> Every one of the 11 shipped rules&#39; <code>fire_cases</code> is a <code>_PURPOSE_BUILT</code> workload:</p><table tabindex="0"><thead><tr><th>rule</th><th>firing cases (all purpose-built)</th></tr></thead><tbody><tr><td><code>sub_self</code></td><td><code>ScalarSelfCancel</code></td></tr><tr><td><code>grammar:pow_one</code></td><td><code>PowOneHead</code></td></tr><tr><td><code>reshape_reshape</code></td><td><code>DoubleReshapeHead</code></td></tr><tr><td><code>square_neg</code></td><td><code>SquareNegHead</code></td></tr><tr><td><code>factor_left</code></td><td><code>SharedFactorMixture</code>, <code>QuadraticFeature</code></td></tr><tr><td><code>factor_right</code></td><td><code>SharedFactorMixtureRight</code></td></tr><tr><td><code>factor_sub_left</code></td><td><code>SharedFactorContrast</code></td></tr><tr><td><code>factor_sub_right</code></td><td><code>SharedFactorContrastRight</code></td></tr><tr><td><code>neg_add</code></td><td><code>NegatedSum</code></td></tr><tr><td><code>exp_add</code></td><td><code>ExpProductHead</code></td></tr><tr><td><code>sub_neg</code></td><td><code>SubNegBias</code></td></tr></tbody></table><p>(<code>factor_left</code>&#39;s second site <code>QuadraticFeature</code> is the <code>d*d + d*e</code> self-product — also the <code>FALSE_mul_factor</code> site.)</p></li></ol><h2 id="the-30-newly-firing-guards-—-real-vs-spelling-gated" tabindex="-1">The 30 newly-firing guards — real vs spelling-gated <a class="header-anchor" href="#the-30-newly-firing-guards-—-real-vs-spelling-gated" aria-label="Permalink to “The 30 newly-firing guards — real vs spelling-gated”">​</a></h2><p>The sweep answers the question at two levels: does the <em>pattern</em> occur on real modules (sites / bare-rule fires), and does the law <em>hold</em> there (<code>equal</code> sites — the region the minted <code>cond</code> must cover; a minted guard&#39;s accepted region is a subset of the equal sites on the measured domain). Result: <strong>all 30 are spelling-gated</strong> — not one has an equal site outside <code>_PURPOSE_BUILT</code>. They split into two honest classes:</p><p><strong>23 guards: the pattern does not occur on real modules at all.</strong><code>census:sub_unsqueeze</code> (→ <code>PairwiseSubLift</code>), <code>exp_add</code>, <code>neg_add</code>, <code>sub_neg</code>, <code>sub_self</code>, <code>square_neg</code>, <code>mul_neg_left</code>, <code>mul_zero</code>, <code>reshape_reshape</code>, <code>factor_left</code>/<code>factor_right</code>/<code>factor_sub_left</code>/ <code>factor_sub_right</code>, <code>grammar:FALSE_mul_factor</code>, <code>grammar:add_inv</code>, <code>grammar:exp_distribute</code>, <code>grammar:neg_distribute</code>, <code>grammar:pow_one</code>, <code>grammar:sigmoid_neg</code>, <code>grammar:square_mul</code>, <code>grammar:sub_add_factor</code>, <code>select_add</code>, <code>select_sub</code> — every equal site is on a purpose-built workload (one case each; <code>factor_left</code> two). (<code>select_add</code>/<code>select_sub</code> dedup to <code>census:add_select</code>/<code>census:sub_select</code> under <code>generator_pools</code>&#39;s merged-pool key order; on the real corpus they are not even <em>proposed</em> — the select-under-elementwise tuple only exists via <code>SelectGateSum</code>/<code>SelectGateDiff</code>.)</p><p><strong>7 wrap/mirror guards: the pattern occurs on real modules, but only in the corner where the law is false.</strong> This is the sharper finding:</p><table tabindex="0"><thead><tr><th>guard</th><th>real-corpus sites (cases)</th><th>equal on real</th><th>equal on purpose-built</th></tr></thead><tbody><tr><td><code>mixed:mul_unsqueeze_l_w</code></td><td>9 sites / 6 cases — <code>SelectiveSSM</code>, <code>HardDispatch</code>, <code>MoEMLP</code>, <code>TopKRouter</code>, <code>ALiBiAttention</code>, <code>LinearAttention</code></td><td><strong>0</strong></td><td>2 (<code>ChannelGateBroadcast</code>, <code>LiftedScalarScale</code>)</td></tr><tr><td><code>mixed:mul_unsqueeze_r_w</code></td><td>5 / 2 — <code>DiagDenseSSM</code>, <code>LinearAttention</code></td><td><strong>0</strong></td><td>2 (<code>HeadGateBroadcast</code>, <code>LiftedScalarScaleRight</code>)</td></tr><tr><td><code>mixed:sub_unsqueeze_l_w</code></td><td>4 / 4 — <code>CodebookQuantizer</code>, <code>ALiBiAttention</code>, <code>RelativePositionBias</code>, <code>SlidingWindowMask</code></td><td><strong>0</strong></td><td>2 (<code>ContrastiveCenter</code>, <code>LiftedScalarCenter</code>)</td></tr><tr><td><code>mixed:mul_chunk_r_id</code></td><td>3 / 3 — <code>RegluMLP</code>, <code>SwiGLU</code>, <code>SwiGLUBlock</code></td><td><strong>0</strong></td><td>1 (<code>SingleChunkGate</code>)</td></tr><tr><td><code>mixed:mul_chunk_r_w</code></td><td>3 / 3 — same</td><td><strong>0</strong></td><td>3</td></tr><tr><td><code>mixed:add_transpose_r_id</code></td><td>4 / 3 — <code>ConformerBlock</code>, <code>PostNormBlock</code>, <code>PreNormBlock</code></td><td><strong>0</strong></td><td>3</td></tr><tr><td><code>mixed:add_transpose_r_w</code></td><td>4 / 3 — same</td><td><strong>0</strong></td><td>3</td></tr></tbody></table><p>Real architectures genuinely spell these shapes — SwiGLU/ReGLU chunk their gate, ALiBi/relative-position code lifts a bias through <code>unsqueeze</code>, Conformer/pre/post-norm blocks add transposed residuals — but always with a <em>non-trivial</em> second operand (a differently-shaped gate, <code>chunks ≥ 2</code>, a real transpose). Those are exactly the sites the minted <code>bcast-eq</code>/<code>axes-noop</code>/<code>chunks==1</code> guard must decline, and the bare-rule sweep confirms it: <code>equal == 0</code> on every real case (some evaluate <code>unequal</code>, some <code>rhs-err</code>/<code>other-err</code> — none equal). The purpose-built spellings are the only places the broadcast-trivial / no-op corner is inhabited. (The pipeline&#39;s <code>fires</code> column still counts these real sites — the e-graph applies the unchecked pattern and the truth gate refuses it downstream — which is why the <code>*_w</code> proposals show <code>intake=1..3</code> fires even real-only.)</p><h2 id="fp64-verify-—-real-vs-purpose-built" tabindex="-1">fp64 verify — real vs purpose-built <a class="header-anchor" href="#fp64-verify-—-real-vs-purpose-built" aria-label="Permalink to “fp64 verify — real vs purpose-built”">​</a></h2><table tabindex="0"><thead><tr><th>subset</th><th>exported</th><th>ingested</th><th>census-only</th><th>verify-failed</th><th>pass rate</th></tr></thead><tbody><tr><td>full corpus</td><td>254</td><td>201</td><td>53</td><td>0</td><td><strong>79.1 %</strong></td></tr><tr><td>real-only</td><td>208</td><td>155</td><td>53</td><td>0</td><td><strong>74.5 %</strong></td></tr><tr><td>purpose-built alone</td><td>46</td><td>46</td><td>0</td><td>0</td><td><strong>100 %</strong></td></tr></tbody></table><p>The gap is a provenance tell: the census-only class is <em>entirely</em> real — torch-native modules whose exported graphs carry ops the bridge has no binding for (<code>broadcast_tensors</code>, <code>affine_grid</code>, …) — while every purpose-built spelling was written inside the bound vocabulary (it had to verify to fill a guard region). Both export rejections are real too (<code>nn.CTCLoss</code> — <code>DynamicOutputShapeException</code>; <code>nn.GaussianNLLLoss</code> — data-dependent guard), unchanged across runs. Purpose-built modules do not &quot;verify differently&quot; — they verify perfectly, <em>because</em> verification was part of their spec.</p><h2 id="what-the-real-corpus-does-yield" tabindex="-1">What the real corpus does yield <a class="header-anchor" href="#what-the-real-corpus-does-yield" aria-label="Permalink to “What the real corpus does yield”">​</a></h2><p>Not zero — just nothing <em>shippable</em>. The honest residual:</p><ul><li><strong>Paying sites exist on real modules.</strong> Nine proposals have <code>paid &gt; 0</code> real-only. Four were already paying on the baseline (<code>mixed:mul_select_l_id</code>, <code>census:mul_select</code>, <code>linear_factor</code>, <code>recognize:softmax</code> — all refused at earlier gates). Four gain paid sites <em>from real intake workloads</em>: <code>mixed:mul_transpose_l_id</code> paid 0 → 4 (<code>AxialAttention</code>, <code>ConformerBlock</code>, <code>PostNormBlock</code>, <code>PreNormBlock</code>, <code>nn.MultiheadAttention</code> — real no-op-transpose sites), <code>mixed:sub_unsqueeze_l_id</code> 0 → 3, <code>mixed:mul_unsqueeze_l_id</code> 1 → 2, <code>mixed:add_unsqueeze_r_id</code> 0 → 1 (<code>RelativePositionBias</code> alone). (<code>mixed:mul_unsqueeze_r_id</code> also fires on <code>intake:LinearAttention</code>, but paid stays at its baseline 1 — the added fire does not pay.)</li><li><strong>All of them are refused at <code>truth</code></strong> — they are the conditional view-identity family (<code>id:same_pairing</code> / <code>unsq:d_in_pad</code> / &quot;no single mechanical feature separates&quot;). The real corpus&#39;s yield bottleneck is not firings or pay; it is that every paying equality on real modules is <em>conditional</em> and the minted guards are never admitted (the auto-cond → gauntlet path&#39;s known limit, unchanged).</li><li>The two proposals minted only on the full corpus, <code>census:add_select</code> and <code>census:sub_select</code>, are the purpose-built&#39;s own census shadows — they vanish with the spellings.</li></ul><h2 id="bottom-line" tabindex="-1">Bottom line <a class="header-anchor" href="#bottom-line" aria-label="Permalink to “Bottom line”">​</a></h2><p>On real modules alone: <strong>0 rules ship, and 0 of the 30 newly-firing guards have a non-empty truth region.</strong> <code>shippable = 11</code> is now <em>measured</em> corpus-circular, not merely argued — the same pipeline, same seed, same gates, minus the 46 spellings, yields nothing shippable. The purpose-built corpus did honest work elsewhere: it proved the guards&#39; regions are inhabitable <em>in principle</em> and it grew the gate stack&#39;s coverage, but it cannot count as evidence that the discovered laws pay on programs nobody wrote to spell them. The real corpus&#39;s genuine signal is the conditional view-identity sites that fire and pay — the next yield lever is admitting (or refuting) those guards, not minting more spellings.</p><h2 id="caveats-limits" tabindex="-1">Caveats / limits <a class="header-anchor" href="#caveats-limits" aria-label="Permalink to “Caveats / limits”">​</a></h2><ul><li><strong>Bare-rule sweep, not re-minted <code>cond</code>s.</strong> The guard table uses the proposals&#39; own <code>check</code>/<code>derive</code> plus fp64 <code>equal</code>/<code>unequal</code> per site — for the unguarded laws that is the firing criterion exactly; for the view guards the minted <code>cond</code>&#39;s accepted region is a subset of the equal sites on the measured domain, so <code>equal == 0</code> on real cases bounds the guarded region from above. (<code>other-err</code>/<code>rhs-err</code> sites were counted but are not firings.)</li><li><strong><code>--real-only</code> writes the filtered census.</strong> Without <code>--out</code>, a real-only run replaces <code>$XDG_CACHE_HOME/mlopt/intake_corpus.json</code> with the real-only subset — consistent with &quot;the file IS what was ingested&quot;, but the full side-file is then gone until re-generated. These runs redirected <code>--out</code>/<code>--tensors</code> to <code>/tmp</code>; the repo state is untouched. Worth a flag or a docstring line if the semantics ever surprise — recorded, not fixed (measurement only).</li><li><strong>Measured, not proven.</strong> Same seeded draws and the same <code>synth_limit</code>-bounded windows as the retro whose numbers this checks; a region outside the corpus is unmeasured by construction.</li><li><strong>The ledger is a judgement call at the edges.</strong> <code>_PURPOSE_BUILT</code> marks the 46 round-3/4 pattern spellings; a couple of earlier compound candidates (e.g. <code>_ScalarRsub</code>) are borderline but stayed &quot;real&quot; — the honest reading does not change if they move.</li><li><strong>Measured at HEAD <code>e2a4051</code>.</strong> Both intake runs and the guard sweep completed before a concurrent in-flight sibling edit (<code>oracle.py</code>, <code>laws/tensor.py</code>, <code>coherence*.py</code>, tests) landed in the working tree ~21:49; the probe&#39;s pipeline re-runs reused the already-imported modules, so every number here is the committed tree&#39;s. Re-run the same two commands to re-measure after that edit settles.</li></ul>`,29)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};